<?php
class HubReports {
    private $store;
    public function __construct($store){$this->store=$store;}
    public function sales($project,$input){$ids=$input['sources']??[];$currency=$input['currency']??'';$grain=$input['grain']??'';$group=$input['group']??'store';if(!is_array($ids)||!$ids||count($ids)>20||!in_array($grain,['order','day'],true)||!is_string($currency)||!preg_match('/^[A-Z]{3}$/D',$currency)||!in_array($group,['store','day','month'],true))throw new RuntimeException('منابع، ارز، سطح و گروه‌بندی گزارش را انتخاب کنید.');$hub=new AiHub($this->store);$stores=[];$groups=[];$provenance=[];$totals=array_fill_keys(['gross','refund','net','orders'],0);$filters=array_filter(['from'=>$input['from']??'','to'=>$input['to']??'','currency'=>$currency,'grain'=>$grain]);
        foreach(array_unique($ids) as $id){$source=$hub->source($project,$id);if(isset($stores[$source['store_id']]))throw new RuntimeException('برای هر فروشگاه فقط یک منبع مرجع انتخاب کنید؛ منابع هم‌پوشان قابل جمع نیستند.');$stores[$source['store_id']]=$id;$offset=0;do{$page=$hub->read($project,$id,'sales',$filters,$offset,500);foreach($page['rows'] as $r){if(in_array($r['status']??'',['cancelled','failed','pending','on-hold','checkout-draft','trash'],true))continue;$key=$group==='store'?$source['store_id']:($group==='month'?substr($r['date'],0,7):$r['date']);if(!isset($groups[$key]))$groups[$key]=array_fill_keys(['gross','refund','net','orders'],0);foreach($totals as $metric=>$v){$groups[$key][$metric]+=$r[$metric];$totals[$metric]+=$r[$metric];}}$offset=$page['next_offset'];}while($offset!==null);$provenance[]=['id'=>$id,'name'=>$source['name'],'store'=>$source['store_id'],'origin'=>$source['origin'],'last_received'=>$source['last_received']['sales']??null];}
        ksort($groups);return ['kind'=>'sales','currency'=>$currency,'grain'=>$grain,'group'=>$group,'filters'=>$filters,'groups'=>$groups,'totals'=>$totals,'sources'=>$provenance,'generated_at'=>gmdate(DATE_ATOM),'warning'=>'Each store uses one selected authority. No currency conversion and no mixing order rows with daily summaries.'];
    }
}
